class Solution {
public:
    int longestPalindrome(vector<string>& words) {
        unordered_map<string, int> count;
        for (const string& w : words) count[w]++;
        int ans = 0;
        bool hasCentral = false;
        for (auto& [word, cnt] : count) {
            if (word[0] == word[1]) {
                ans += (cnt / 2) * 4;
                if (cnt % 2 == 1) hasCentral = true;
            } else if (word[0] < word[1]) {
                string rev = {word[1], word[0]};
                if (count.count(rev)) {
                    ans += min(cnt, count[rev]) * 4;
                }
            }
        }
        if (hasCentral) ans += 2;
        return ans;
    }
};

class Solution {
    public int longestPalindrome(String[] words) {
        Map<String, Integer> count = new HashMap<>();
        for (String w : words) count.put(w, count.getOrDefault(w, 0) + 1);
        int ans = 0;
        boolean hasCentral = false;
        for (Map.Entry<String, Integer> entry : count.entrySet()) {
            String word = entry.getKey();
            int cnt = entry.getValue();
            if (word.charAt(0) == word.charAt(1)) {
                ans += (cnt / 2) * 4;
                if (cnt % 2 == 1) hasCentral = true;
            } else if (word.charAt(0) < word.charAt(1)) {
                String rev = "" + word.charAt(1) + word.charAt(0);
                int revCnt = count.getOrDefault(rev, 0);
                ans += Math.min(cnt, revCnt) * 4;
            }
        }
        if (hasCentral) ans += 2;
        return ans;
    }
}

var longestPalindrome = function(words) {
    const count = new Map();
    for (const w of words) count.set(w, (count.get(w) || 0) + 1);
    let ans = 0, hasCentral = false;
    for (const [word, cnt] of count.entries()) {
        if (word[0] === word[1]) {
            ans += Math.floor(cnt / 2) * 4;
            if (cnt % 2 === 1) hasCentral = true;
        } else if (word[0] < word[1]) {
            const rev = word[1] + word[0];
            const revCnt = count.get(rev) || 0;
            ans += Math.min(cnt, revCnt) * 4;
        }
    }
    if (hasCentral) ans += 2;
    return ans;
};
